/// Builder for a [`Program`].
///
/// Constructs the node in place in the memory arena.
/// Created by [`Program::build`].
///
/// `State` records which fields have been set - see [`FieldsState`].
/// [`finish`] is only callable once they are all [`Set`].
///
/// [`finish`]: Self::finish
#[must_use]
#[repr(transparent)]
pub struct ProgramBuilder<'a, Target, State> {
    target: Target,
    marker: PhantomData<(&'a (), State)>,
}

impl<'a> Program<'a> {
    /// Start building a [`Program`] in the memory arena.
    ///
    /// Set every field on the returned builder, then call [`finish`].
    ///
    /// [`finish`]: ProgramBuilder::finish
    #[inline(always)]
    pub fn build(
        builder: &impl GetAstBuilder<'a>,
    ) -> ProgramBuilder<'a, OwnedSlot<'a, Self>, NoFieldsSet> {
        let builder = builder.builder();
        ProgramBuilder::new(OwnedSlot::new_in(&builder.allocator()), builder)
    }

    /// Reserve memory in the arena for a [`Program`], without initializing it.
    ///
    /// Returns a [`Box`] of uninitialized memory.
    /// Write the node into it with [`fill`], or [`fill_with`].
    ///
    /// [`Box`]: ArenaBox
    /// [`fill`]: ArenaBox::fill
    /// [`fill_with`]: ArenaBox::fill_with
    #[inline(always)]
    pub fn uninit(allocator: &impl GetAllocator<'a>) -> ArenaBox<'a, MaybeUninit<Self>> {
        ArenaBox::new_uninit_in(&allocator.allocator())
    }
}

impl<'a> SlotBuild<'a> for Slot<'_, Program<'a>> {
    type Builder = ProgramBuilder<'a, Self, NoFieldsSet>;

    /// Build the [`Program`] in place, in this [`Slot`].
    #[inline(always)]
    fn build(self, builder: &impl GetAstBuilder<'a>) -> Self::Builder {
        ProgramBuilder::new(self, builder.builder())
    }
}

impl<'a, Target: BuilderTarget<Program<'a>>> ProgramBuilder<'a, Target, NoFieldsSet> {
    #[inline(always)]
    fn new(mut target: Target, builder: &impl AstBuild<'a>) -> Self {
        unsafe { init_node_id(&raw mut (*target.as_mut_ptr()).node_id, builder) };
        Self { target, marker: PhantomData }
    }
}

impl<'a, Target, State> ProgramBuilder<'a, Target, State>
where
    Target: BuilderTarget<Program<'a>>,
    State: FieldsState,
{
    /// Set `span` start on the [`Program`] being built.
    #[inline(always)]
    pub fn span_start(mut self, span_start: u32) -> ProgramBuilder<'a, Target, State::Set1> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).span.start).write(span_start) };
        self.transition()
    }

    /// Set `span` end on the [`Program`] being built.
    #[inline(always)]
    pub fn span_end(mut self, span_end: u32) -> ProgramBuilder<'a, Target, State::Set2> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).span.end).write(span_end) };
        self.transition()
    }

    /// Set `span` on the [`Program`] being built.
    #[inline(always)]
    pub fn span(mut self, span: Span) -> ProgramBuilder<'a, Target, State::Set1And2> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).span).write(span) };
        self.transition()
    }

    /// Set `source_type` on the [`Program`] being built.
    #[inline(always)]
    pub fn source_type(
        mut self,
        source_type: SourceType,
    ) -> ProgramBuilder<'a, Target, State::Set3> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).source_type).write(source_type) };
        self.transition()
    }

    /// Set `source_text` on the [`Program`] being built.
    #[inline(always)]
    pub fn source_text(mut self, source_text: &'a str) -> ProgramBuilder<'a, Target, State::Set4> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).source_text).write(source_text) };
        self.transition()
    }

    /// Set `comments` on the [`Program`] being built.
    #[inline(always)]
    pub fn comments(
        mut self,
        comments: ArenaVec<'a, Comment>,
    ) -> ProgramBuilder<'a, Target, State::Set5> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).comments).write(comments) };
        self.transition()
    }

    /// Set `comments` on the [`Program`] being built, in place.
    ///
    /// `fill` is given a [`Slot`] for the `comments` field.
    /// It must fill the slot, and return the [`SlotFilled`] token which that produces.
    #[inline(always)]
    pub fn comments_with(
        mut self,
        fill: impl for<'slot> FnOnce(Slot<'slot, ArenaVec<'a, Comment>>) -> SlotFilled<'slot>,
    ) -> ProgramBuilder<'a, Target, State::Set5> {
        let slot = unsafe { Slot::new(&raw mut (*self.target.as_mut_ptr()).comments) };
        fill(slot);
        self.transition()
    }

    /// Set `hashbang` on the [`Program`] being built.
    #[inline(always)]
    pub fn hashbang(
        mut self,
        hashbang: Option<Hashbang<'a>>,
    ) -> ProgramBuilder<'a, Target, State::Set6> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).hashbang).write(hashbang) };
        self.transition()
    }

    /// Set `hashbang` on the [`Program`] being built, in place.
    ///
    /// `fill` is given a [`Slot`] for the `hashbang` field.
    /// It must fill the slot, and return the [`SlotFilled`] token which that produces.
    #[inline(always)]
    pub fn hashbang_with(
        mut self,
        fill: impl for<'slot> FnOnce(Slot<'slot, Option<Hashbang<'a>>>) -> SlotFilled<'slot>,
    ) -> ProgramBuilder<'a, Target, State::Set6> {
        let slot = unsafe { Slot::new(&raw mut (*self.target.as_mut_ptr()).hashbang) };
        fill(slot);
        self.transition()
    }

    /// Set `directives` on the [`Program`] being built.
    #[inline(always)]
    pub fn directives(
        mut self,
        directives: ArenaVec<'a, Directive<'a>>,
    ) -> ProgramBuilder<'a, Target, State::Set7> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).directives).write(directives) };
        self.transition()
    }

    /// Set `directives` on the [`Program`] being built, in place.
    ///
    /// `fill` is given a [`Slot`] for the `directives` field.
    /// It must fill the slot, and return the [`SlotFilled`] token which that produces.
    #[inline(always)]
    pub fn directives_with(
        mut self,
        fill: impl for<'slot> FnOnce(Slot<'slot, ArenaVec<'a, Directive<'a>>>) -> SlotFilled<'slot>,
    ) -> ProgramBuilder<'a, Target, State::Set7> {
        let slot = unsafe { Slot::new(&raw mut (*self.target.as_mut_ptr()).directives) };
        fill(slot);
        self.transition()
    }

    /// Set `body` on the [`Program`] being built.
    #[inline(always)]
    pub fn body(
        mut self,
        body: ArenaVec<'a, Statement<'a>>,
    ) -> ProgramBuilder<'a, Target, State::Set8> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).body).write(body) };
        self.transition()
    }

    /// Set `body` on the [`Program`] being built, in place.
    ///
    /// `fill` is given a [`Slot`] for the `body` field.
    /// It must fill the slot, and return the [`SlotFilled`] token which that produces.
    #[inline(always)]
    pub fn body_with(
        mut self,
        fill: impl for<'slot> FnOnce(Slot<'slot, ArenaVec<'a, Statement<'a>>>) -> SlotFilled<'slot>,
    ) -> ProgramBuilder<'a, Target, State::Set8> {
        let slot = unsafe { Slot::new(&raw mut (*self.target.as_mut_ptr()).body) };
        fill(slot);
        self.transition()
    }

    /// Set `scope_id` on the [`Program`] being built.
    #[inline(always)]
    pub fn scope_id(mut self, scope_id: ScopeId) -> ProgramBuilder<'a, Target, State::Set9> {
        unsafe { (&raw mut (*self.target.as_mut_ptr()).scope_id).write(Cell::new(Some(scope_id))) };
        self.transition()
    }

    /// Set `scope_id` field of the [`Program`]
    /// to its default value, if it's not been set already.
    #[inline(always)]
    pub fn defaults(mut self) -> ProgramBuilder<'a, Target, State::Set9> {
        if !State::Field9::IS_SET {
            unsafe { (&raw mut (*self.target.as_mut_ptr()).scope_id).write(Default::default()) };
        }

        self.transition()
    }

    /// Finish building the [`Program`].
    ///
    /// Returns a [`Box`](ArenaBox) containing the node, or - if the node is being built
    /// into a field of its parent - a [`SlotFilled`] token.
    ///
    /// Only callable once every field has been set.
    #[inline(always)]
    pub fn finish(self) -> Target::Output
    where
        State::Field1: SpanStartIsSet,
        State::Field2: SpanEndIsSet,
        State::Field3: SourceTypeIsSet,
        State::Field4: SourceTextIsSet,
        State::Field5: CommentsIsSet,
        State::Field6: HashbangIsSet,
        State::Field7: DirectivesIsSet,
        State::Field8: BodyIsSet,
        State::Field9: ScopeIdIsSet,
    {
        unsafe { self.target.assume_filled() }
    }

    /// Build the [`Program`] by handing this builder to `build`.
    ///
    /// `build` is given this builder, re-targeted to write into a [`Slot`].
    /// Fields already set stay set. `build` sets whatever is left, then calls `finish`.
    #[inline(always)]
    pub fn with(
        mut self,
        build: impl for<'slot> FnOnce(
            ProgramBuilder<'a, Slot<'slot, Program<'a>>, State>,
        ) -> SlotFilled<'slot>,
    ) -> Target::Output {
        let inner = ProgramBuilder { target: self.target.reborrow(), marker: PhantomData };
        build(inner);
        unsafe { self.target.assume_filled() }
    }

    #[inline(always)]
    fn transition<NewState>(self) -> ProgramBuilder<'a, Target, NewState> {
        ProgramBuilder { target: self.target, marker: PhantomData }
    }
}

