/// Every trait needed to build AST nodes in [`Slot`]s, for importing as a group.
///
/// [`SlotBuild`] provides `Slot::build`.
/// Each enum's `into_<variant>` methods come from its own trait.
/// To make all these methods available, import:
///
/// ```ignore
/// use oxc_ast::builder::builders::traits::*;
/// ```
pub mod traits {
    pub use crate::builder::builders::SlotBuild;

    pub use super::{
        ArgumentSlot, ArrayExpressionElementSlot, ArrowFunctionBodySlot,
        AssignmentTargetMaybeDefaultSlot, AssignmentTargetPatternSlot,
        AssignmentTargetPropertySlot, AssignmentTargetSlot, BindingPatternSlot, ChainElementSlot,
        ClassElementSlot, DeclarationSlot, ExportDefaultDeclarationKindSlot, ExpressionSlot,
        ForStatementInitSlot, ForStatementLeftSlot, ImportAttributeKeySlot,
        ImportDeclarationSpecifierSlot, JSXAttributeItemSlot, JSXAttributeNameSlot,
        JSXAttributeValueSlot, JSXChildSlot, JSXElementNameSlot, JSXExpressionSlot,
        JSXMemberExpressionObjectSlot, MemberExpressionSlot, ModuleDeclarationSlot,
        ModuleExportNameSlot, ObjectPropertyKindSlot, PropertyKeySlot, SimpleAssignmentTargetSlot,
        StatementSlot, TSEnumMemberNameSlot, TSImportTypeQualifierSlot, TSLiteralSlot,
        TSModuleReferenceSlot, TSNamespaceDeclarationBodySlot, TSSignatureSlot, TSTupleElementSlot,
        TSTypeNameSlot, TSTypePredicateNameSlot, TSTypeQueryExprNameSlot, TSTypeSlot,
    };
}
